t.script:
(function(){ var k='md_wait_'+location.pathname; var n=+(sessionStorage.getItem(k)||0);
  if(n<15){ sessionStorage.setItem(k,n+1); setTimeout(function(){ location.reload(); },3000); }
  else { var d=document.getElementById('md_code_box'); if(d) d.insertAdjacentHTML('beforeend','<div style="margin-top:8px">Está tardando más de lo normal. Te llegará por correo en unos minutos.</div>'); } })();
